from runtime_sdk import NodeContext


def run(ctx: NodeContext):
    """记忆：短期（state）与长期（SQLite）读写。"""
    action = ctx.params.get("action", "write")
    key = ctx.params.get("key", "memory")
    if action == "read":
        return ctx.recall(key, "")
    ctx.remember(key, ctx.text, long_term=ctx.params.get("long_term", True))
    return ctx.text

from runtime_sdk import NodeContext


def run(ctx: NodeContext):
    """KV 存储：键值读写，适合存中间结果与状态。"""
    key = ctx.params.get("key") or "default"
    if (ctx.params.get("action") or "get") == "set":
        ctx.kv_set(key, ctx.text)
        return {"key": key, "value": ctx.text}
    return {"key": key, "value": ctx.kv_get(key) or ""}

